/**
 * « Expliquer » for the audit / API journals: a short plain-French explanation
 * of one log line, generated by Groq on the free tier.
 *
 * Quota-safe: answers are cached for 30 days (KV, or app_config when KV is not
 * bound), there is a daily cap (GROQ_AUDIT_EXPLAIN_DAILY_LIMIT, default 60),
 * a 429 pauses the feature, and when Groq is unavailable a deterministic
 * explanation is returned instead, so the button always answers.
 */
import { classifyNetwork } from './apiLog';

export const AUDIT_EXPLAIN_MODEL = 'openai/gpt-oss-20b';

export type ExplainInput = {
  kind: 'audit' | 'api';
  id: number;
  created_at?: string | null;
  username?: string | null;
  role?: string | null;
  action?: string | null;
  entity?: string | null;
  entity_id?: string | null;
  detail?: string | null;
  method?: string | null;
  path?: string | null;
  status?: number | null;
  ms?: number | null;
  ip?: string | null;
  country?: string | null;
  city?: string | null;
  asn?: number | null;
  as_org?: string | null;
  ua?: string | null;
  /** Same IP seen with other users / failures in the last 24 h (context). */
  ip_recent_failures?: number;
  ip_recent_users?: number;
};

export type Explanation = {
  summary: string;
  risk: 'normal' | 'à surveiller' | 'suspect';
  advice: string;
  source: 'groq' | 'rules' | 'cache';
  model?: string;
};

type Env = { DB?: D1Database; CACHE?: KVNamespace; GROQ_API_KEY?: string; GROQ_AUDIT_EXPLAIN_DAILY_LIMIT?: string; GROQ_AUDIT_EXPLAIN_MODEL?: string };
type Fetcher = (url: string, init: RequestInit) => Promise<Response>;

const SYSTEM = [
  'Tu es l’assistant sécurité d’Atlas Commerce (gestion de stock et facturation, Maroc).',
  'On te donne UNE ligne du journal d’audit ou du journal des appels API.',
  'Explique en français simple, pour un gérant non technicien, ce qui s’est passé.',
  'Réponds en JSON strict : {"summary": "...", "risk": "normal|à surveiller|suspect", "advice": "..."}.',
  'summary : 1 à 3 phrases (qui, quoi, quand, d’où). advice : 1 phrase actionnable, ou "Rien à faire." si normal.',
  'Un VPN/hébergeur, plusieurs échecs 401/403 depuis la même IP, ou un pays inhabituel rendent la ligne « à surveiller » ou « suspecte ».',
  'N’invente rien qui ne soit pas dans les données.',
].join('\n');

function linesFor(input: ExplainInput): string {
  const net = classifyNetwork(input.as_org, input.asn);
  const rows: [string, unknown][] = [
    ['type', input.kind === 'api' ? 'appel API' : 'action d’audit'],
    ['date (UTC)', input.created_at],
    ['utilisateur', input.username || '(anonyme)'],
    ['rôle', input.role],
    ['action', input.action],
    ['objet', input.entity ? `${input.entity}${input.entity_id ? ` #${input.entity_id}` : ''}` : null],
    ['détail', input.detail ? String(input.detail).slice(0, 400) : null],
    ['requête', input.method && input.path ? `${input.method} ${input.path}` : null],
    ['statut HTTP', input.status],
    ['durée', input.ms != null ? `${input.ms} ms` : null],
    ['IP', input.ip],
    ['lieu', [input.city, input.country].filter(Boolean).join(', ') || null],
    ['réseau', input.as_org ? `${input.as_org}${input.asn ? ` (AS${input.asn})` : ''} → ${net.label}` : null],
    ['navigateur', input.ua ? String(input.ua).slice(0, 160) : null],
    ['échecs récents depuis cette IP (24 h)', input.ip_recent_failures],
    ['comptes distincts depuis cette IP (24 h)', input.ip_recent_users],
  ];
  return rows.filter(([, v]) => v !== null && v !== undefined && v !== '').map(([k, v]) => `- ${k} : ${v}`).join('\n');
}

const HTTP_FR: Record<number, string> = {
  400: 'requête invalide', 401: 'non authentifié (session absente ou expirée)', 403: 'accès refusé',
  404: 'ressource introuvable', 409: 'conflit', 413: 'données trop volumineuses', 422: 'données refusées',
  426: 'application trop ancienne', 429: 'trop de requêtes', 500: 'erreur serveur', 503: 'service indisponible',
};

/** Deterministic fallback: always available, no quota. */
export function ruleExplanation(input: ExplainInput): Explanation {
  const net = classifyNetwork(input.as_org, input.asn);
  const where = [input.city, input.country].filter(Boolean).join(', ');
  const from = `${input.ip ? `depuis l’IP ${input.ip}` : ''}${where ? ` (${where})` : ''}${input.as_org ? `, réseau ${input.as_org}` : ''}`;
  const who = input.username ? `« ${input.username} »` : 'Un visiteur non connecté';
  let summary: string;
  let risk: Explanation['risk'] = 'normal';
  if (input.kind === 'api') {
    const st = Number(input.status) || 0;
    const what = `${input.method || ''} ${input.path || ''}`.trim();
    summary = `${who} a appelé ${what} ${from}. Réponse ${st}${HTTP_FR[st] ? ` : ${HTTP_FR[st]}` : st < 400 ? ' : succès' : ''}${input.ms != null ? ` en ${input.ms} ms` : ''}.`;
    if (st === 401 || st === 403) risk = (input.ip_recent_failures || 0) >= 5 ? 'suspect' : 'à surveiller';
    else if (st >= 500) risk = 'à surveiller';
  } else {
    summary = `${who} a effectué « ${input.action || 'action'} »${input.entity ? ` sur ${input.entity}${input.entity_id ? ` #${input.entity_id}` : ''}` : ''} ${from}.${input.detail ? ` Détail : ${String(input.detail).slice(0, 160)}.` : ''}`;
    if (/fail|échec|denied|refus|blocked|bloqu/i.test(`${input.action} ${input.detail}`)) risk = 'à surveiller';
  }
  if (net.risky && risk === 'normal') risk = 'à surveiller';
  if (net.risky && risk === 'à surveiller' && (input.ip_recent_failures || 0) >= 5) risk = 'suspect';
  const advice = risk === 'normal'
    ? 'Rien à faire.'
    : net.risky
      ? `Connexion via ${net.label.toLowerCase()} : vérifiez que c’est bien ${input.username || 'un membre de l’équipe'} ; sinon révoquez ses sessions et changez le mot de passe.`
      : risk === 'suspect'
        ? 'Plusieurs échecs depuis cette IP : bloquez-la dans Sécurité si elle ne vous dit rien.'
        : 'Surveillez si cela se répète.';
  return { summary: summary.replace(/\s+/g, ' ').trim(), risk, advice, source: 'rules' };
}

function parse(raw: string, model: string): Explanation | null {
  try {
    const j = JSON.parse(raw.replace(/^```(?:json)?|```$/g, '').trim());
    const summary = String(j.summary || '').trim().slice(0, 600);
    if (!summary) return null;
    const r = String(j.risk || '').toLowerCase();
    const risk: Explanation['risk'] = r.startsWith('susp') ? 'suspect' : r.includes('surveil') ? 'à surveiller' : 'normal';
    return { summary, risk, advice: String(j.advice || 'Rien à faire.').trim().slice(0, 300), source: 'groq', model };
  } catch { return null; }
}

async function cfg(db: D1Database | undefined, key: string, value?: string): Promise<string> {
  if (!db) return '';
  try {
    if (value === undefined) {
      const row = await db.prepare('SELECT value FROM app_config WHERE key = ?').bind(key).first() as any;
      return String(row?.value || '');
    }
    await db.prepare(`INSERT INTO app_config (key, value, updated_at) VALUES (?, ?, datetime('now'))
      ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`).bind(key, value).run();
  } catch { /* bookkeeping only */ }
  return '';
}

export async function explainLogLine(env: Env, input: ExplainInput, fetcher: Fetcher = fetch): Promise<Explanation> {
  const cacheKey = `audit_explain:v1:${input.kind}:${input.id}`;
  try {
    const hit = env.CACHE ? await env.CACHE.get(cacheKey) : null;
    if (hit) return { ...(JSON.parse(hit) as Explanation), source: 'cache' };
  } catch { /* */ }
  const fallback = ruleExplanation(input);
  const key = String(env.GROQ_API_KEY || '').trim();
  if (!key) return fallback;
  const limitRaw = Number(env.GROQ_AUDIT_EXPLAIN_DAILY_LIMIT);
  const limit = Number.isFinite(limitRaw) && limitRaw >= 0 ? Math.min(500, Math.floor(limitRaw)) : 60;
  try {
    if (limit <= 0) return fallback;
    const pause = Number(await cfg(env.DB, 'groq_audit_explain_pause'));
    if (pause && pause > Date.now()) return fallback;
    const today = new Date().toISOString().slice(0, 10);
    const [d, n] = (await cfg(env.DB, 'groq_audit_explain_usage')).split(':');
    const used = d === today ? Number(n) || 0 : 0;
    if (used >= limit) return fallback;
    await cfg(env.DB, 'groq_audit_explain_usage', `${today}:${used + 1}`);
    const model = String(env.GROQ_AUDIT_EXPLAIN_MODEL || AUDIT_EXPLAIN_MODEL).slice(0, 80);
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 8000);
    let res: Response;
    try {
      res = await fetcher('https://api.groq.com/openai/v1/chat/completions', {
        method: 'POST',
        redirect: 'manual',
        signal: controller.signal,
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model,
          temperature: 0.2,
          max_tokens: 400,
          ...(model.startsWith('openai/gpt-oss') ? { reasoning_effort: 'low' } : {}),
          response_format: { type: 'json_object' },
          messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: linesFor(input) }],
        }),
      });
    } finally { clearTimeout(timer); }
    if (res.status === 429) {
      const retry = Number(res.headers.get('retry-after')) || 300;
      await cfg(env.DB, 'groq_audit_explain_pause', String(Date.now() + Math.min(Math.max(60, retry), 6 * 3600) * 1000));
      return fallback;
    }
    if (!res.ok) return fallback;
    const j: any = await res.json().catch(() => null);
    const out = parse(String(j?.choices?.[0]?.message?.content || ''), model);
    if (!out) return fallback;
    try { await env.CACHE?.put(cacheKey, JSON.stringify(out), { expirationTtl: 30 * 86400 }); } catch { /* */ }
    return out;
  } catch {
    return fallback;
  }
}
